import com.wolinski.shop.platform.ShopProblem;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

/** A percentage typed by a person, as whole basis points: 12.5 is 1250. */
final class DiscountRate {

    private static final Pattern PERCENT = Pattern.compile("(\\d{1,3})(?:\\.(\\d{1,2}))?");
    private static final long MAX_BASIS_POINTS = 10_000;

    private DiscountRate() {
    }

    static long parseBasisPoints(String text) {
        Matcher m = PERCENT.matcher(null == text ? "" : text.trim());
        if (!m.matches()) {
            throw new ShopProblem("INVALID_PERCENT", "Percent must look like 12 or 12.5, at most two decimals: " + text);
        }
        long whole = Long.parseLong(m.group(1));
        String fraction = null == m.group(2) ? "" : m.group(2);
        long hundredths = fraction.isEmpty() ? 0 : Long.parseLong(fraction) * (fraction.length() == 1 ? 10 : 1);
        long basisPoints = whole * 100 + hundredths;
        if (basisPoints > MAX_BASIS_POINTS) {
            throw new ShopProblem("PERCENT_OUT_OF_RANGE", "Percent must be between 0 and 100: " + text);
        }
        return basisPoints;
    }
}
}

