import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertThrows;

import com.wolinski.shop.money.Money;
import com.wolinski.shop.orders.api.OrderFacade;
import com.wolinski.shop.platform.ShopProblem;
import java.time.Instant;
import org.junit.jupiter.api.Test;
import org.springframework.context.annotation.AnnotationConfigApplicationContext;

class OrderDiscountTest {

    private static final Instant NOW = Instant.parse("2026-10-01T10:00:00Z");

    @Test
    void discountRoundsHalfUpToAMinorUnit() {
        try (var shop = new AnnotationConfigApplicationContext(ShopConfig.class)) {
            OrderFacade orders = shop.getBean(OrderFacade.class);
            String id = orders.place("c-1", Money.pln(100), NOW);

            orders.applyDiscount(id, "0.5");

            assertEquals(Money.pln(99), orders.summary(id).total());
        }
    }

    @Test
    void percentageDiscountIsApplied() {
        try (var shop = new AnnotationConfigApplicationContext(ShopConfig.class)) {
            OrderFacade orders = shop.getBean(OrderFacade.class);
            String id = orders.place("c-1", Money.pln(1000), NOW);

            orders.applyDiscount(id, "12.5");

            assertEquals(Money.pln(875), orders.summary(id).total());
        }
    }

    @Test
    void halfOfAMinorUnitRoundsUp() {
        try (var shop = new AnnotationConfigApplicationContext(ShopConfig.class)) {
            OrderFacade orders = shop.getBean(OrderFacade.class);
            String id = orders.place("c-1", Money.pln(5), NOW);

            orders.applyDiscount(id, "50");

            assertEquals(Money.pln(2), orders.summary(id).total());
        }
    }

    @Test
    void invalidPercentIsRejected() {
        try (var shop = new AnnotationConfigApplicationContext(ShopConfig.class)) {
            OrderFacade orders = shop.getBean(OrderFacade.class);
            String id = orders.place("c-1", Money.pln(1000), NOW);

            assertThrows(ShopProblem.class, () -> orders.applyDiscount(id, "12,5"));
            assertThrows(ShopProblem.class, () -> orders.applyDiscount(id, "12.555"));
            assertThrows(ShopProblem.class, () -> orders.applyDiscount(id, "-1"));
            assertThrows(ShopProblem.class, () -> orders.applyDiscount(id, "100.01"));
            assertThrows(ShopProblem.class, () -> orders.applyDiscount(id, "abc"));
            assertThrows(ShopProblem.class, () -> orders.applyDiscount(id, ""));

            assertEquals(Money.pln(1000), orders.summary(id).total());
        }
    }
}
}
